package android.app.job;import android.content.Context;import java.util.concurrent.CountDownLatch;public abstract class JobService extends Context {public static CountDownLatch finished=new CountDownLatch(1);public static boolean retry;public void jobFinished(JobParameters p,boolean r){retry=r;finished.countDown();}public abstract boolean onStartJob(JobParameters p);public abstract boolean onStopJob(JobParameters p);}
